import { createHash } from "node:crypto";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";

const root = process.cwd();
const output = path.resolve(process.argv[2] ?? path.join(root, "build", "stage6-release"));
const lock = await readFile(path.join(root, "gradle", "libs.versions.toml"), "utf8");
const pnpmLock = await readFile(path.join(root, "pnpm-lock.yaml"), "utf8");
const components = [];
for (const match of lock.matchAll(/module = "([^"]+)", version\.ref = "([^"]+)"/g)) {
  components.push({ type: "library", name: match[1], versionReference: match[2] });
}
for (const match of pnpmLock.matchAll(/^\s{2}([^\s][^:]+):\s*$/gm)) {
  const name = match[1].replace(/^['"]|['"]$/g, "");
  if (name.includes("@") || name.includes("/")) components.push({ type: "library", name });
}
components.sort((a, b) => a.name.localeCompare(b.name));
const serialNumber = `urn:uuid:${createHash("sha256").update(JSON.stringify(components)).digest("hex").slice(0, 32)}`;
const bom = {
  bomFormat: "CycloneDX", specVersion: "1.6", serialNumber, version: 1,
  metadata: { component: { type: "application", name: "ji", version: "0.1.0-SNAPSHOT" },
    properties: [{ name: "ji.release.public", value: "false" }] },
  components,
};
await mkdir(output, { recursive: true });
await writeFile(path.join(output, "ji.cdx.json"), `${JSON.stringify(bom, null, 2)}\n`);
process.stdout.write(`${path.join(output, "ji.cdx.json")}\n`);
